-- Migration 017: Phase Specific Assignments
-- Separates Survey Phase assignments from Camp Phase assignments.

-- 1. Add phase column to camp_people table (nullable)
ALTER TABLE public.camp_people ADD COLUMN IF NOT EXISTS phase TEXT CHECK (phase IN ('survey', 'camp'));

-- 2. Drop the old unique constraint (camp_id, person_id, camp_role)
-- The default constraint name generated by PostgreSQL for UNIQUE(camp_id, person_id, camp_role) is camp_people_camp_id_person_id_camp_role_key
ALTER TABLE public.camp_people DROP CONSTRAINT IF EXISTS camp_people_camp_id_person_id_camp_role_key;

-- 3. Add new unique index for active phase-scoped assignments
CREATE UNIQUE INDEX IF NOT EXISTS camp_people_active_phase_idx 
  ON public.camp_people (camp_id, person_id, phase) 
  WHERE phase IS NOT NULL;

-- 4. Add unique index for legacy neutral assignments to prevent duplicates
CREATE UNIQUE INDEX IF NOT EXISTS camp_people_legacy_phase_idx 
  ON public.camp_people (camp_id, person_id) 
  WHERE phase IS NULL;
